type Page='Overview'|'Agreements'|'Vehicles'|'Customers'|'Owners'|'Drivers'|'Expenses'|'Billing'|'Owner payables'|'Payroll'|'Settlements'|'Cashbook'|'Reports'|'Notifications'|'Settings'|'Actor portal';
const nav:[string,Page,React.ComponentType<{size?:number;className?:string}>][]=[['WORKSPACE','Overview',LayoutDashboard],['MANAGE','Agreements',FileSignature],['','Vehicles',CarFront],['','Customers',UsersRound],['','Owners',Building2],['','Drivers',UserRound],['FINANCE','Expenses',ReceiptText],['','Billing',WalletCards],['','Owner payables',HandCoins],['','Payroll',Banknote],['','Settlements',Layers3],['','Cashbook',BookOpen],['','Reports',ChartNoAxesCombined],['SYSTEM','Notifications',Bell],['','Settings',Settings2]];
const pages=nav.map(x=>x[1]).concat('Actor portal');
const today='2026-09-23';
const fmtDate=(x:string)=>new Date(x+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
function Badge({children,tone='neutral'}:{children:React.ReactNode;tone?:'neutral'|'good'|'warn'|'bad'|'blue'}){return <span className={'badge badge-'+tone}>{children}</span>}
function Card({children,className=''}:{children:React.ReactNode;className?:string}){return <section className={'card soft-shadow '+className}>{children}</section>}
function SectionHeading({title,subtitle,action}:{title:string;subtitle?:string;action?:React.ReactNode}){return <div className="section-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>}
function Empty({text}:{text:string}){return <div className="empty"><ClipboardList size={25}/><p>{text}</p></div>}
function csv(rows:(string|number)[][],filename:string){const content=rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n');const blob=new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}

export default function Home(){
 const [store,setStore]=useState<Store>(apiMode?{agreements:[],entries:[],notices:[],closed:[]}:seed),[ready,setReady]=useState(false),[apiError,setApiError]=useState(''),[apiBusy,setApiBusy]=useState(false),[entryKey,setEntryKey]=useState('');
 const [page,setPage]=useState<Page>('Overview'),[selected,setSelected]=useState<string|null>(null),[entryOpen,setEntryOpen]=useState(false),[agreementOpen,setAgreementOpen]=useState(false),[confirmClose,setConfirmClose]=useState<string|null>(null),[mobileMenu,setMobileMenu]=useState(false),[toast,setToast]=useState('');
 const [search,setSearch]=useState(''),[statusFilter,setStatusFilter]=useState('All'),[ownerFilter,setOwnerFilter]=useState('All owners'),[sort,setSort]=useState<'customer'|'due'>('customer'),[role,setRole]=useState<'Owner'|'Driver'|'Customer'>('Owner'),[actor,setActor]=useState('Farhana Rahman');
 const [entryType,setEntryType]=useState<EntryType>('Expense'),[entryAgreement,setEntryAgreement]=useState('AGR-1042'),[entryAmount,setEntryAmount]=useState(''),[entryCategory,setEntryCategory]=useState('Repair'),[entryPayer,setEntryPayer]=useState('Operator'),[entryLiable,setEntryLiable]=useState('Owner'),[entryDate,setEntryDate]=useState(today),[entryRef,setEntryRef]=useState(''),[entryDesc,setEntryDesc]=useState(''),[entryOffset,setEntryOffset]=useState(true),[entryReceipt,setEntryReceipt]=useState(''),[entryError,setEntryError]=useState('');
 const [newAgreement,setNewAgreement]=useState({customer:'',vehicle:'',registration:'',owner:'',driver:'',rent:'',ownerRent:'',salary:'',start:today,fuel:'Owner',repair:'Owner',offset:true}),[wizardStep,setWizardStep]=useState(0),[wizardError,setWizardError]=useState('');
 const [reportType,setReportType]=useState('Vehicle contribution');
 useEffect(()=>{if(apiMode){liveSnapshot().then(setStore).catch(e=>setApiError(e.message)).finally(()=>setReady(true))}else{setStore(loadDemo());setReady(true)}const read=()=>{const p=new URLSearchParams(location.search);const v=p.get('view') as Page|null;setPage(v&&pages.includes(v)?v:'Overview');setSearch(p.get('q')||'');setOwnerFilter(p.get('owner')||'All owners');setStatusFilter(p.get('status')||'All')};read();addEventListener('popstate',read);return()=>removeEventListener('popstate',read)},[]);
 useEffect(()=>{if(ready&&!apiMode)saveDemo(store)},[store,ready]);
 const refreshLive=async()=>{const next=await liveSnapshot();setStore(next);setApiError('');return next};
 useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(id)},[toast]);
 const navigate=(p:Page)=>{setPage(p);setSelected(null);setMobileMenu(false);const u=new URL(location.href);u.searchParams.set('view',p);history.pushState({},'',u)};
 const filterURL=(key:string,value:string)=>{const u=new URL(location.href);if(!value||value==='All'||value==='All owners')u.searchParams.delete(key);else u.searchParams.set(key,value);history.replaceState({},'',u)};
 const changeSearch=(v:string)=>{setSearch(v);filterURL('q',v)};
 const changeOwner=(v:string)=>{setOwnerFilter(v);filterURL('owner',v)};
 const changeStatus=(v:string)=>{setStatusFilter(v);filterURL('status',v)};
 const related=store.agreements.filter(a=>(ownerFilter==='All owners'||a.owner===ownerFilter)&&[a.customer,a.vehicle,a.registration,a.owner,a.driver,a.id].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='due'?statement(b,store.entries).customerDue-statement(a,store.entries).customerDue:a.customer.localeCompare(b.customer));
 const financial=totals(store),current=store.agreements.find(a=>a.id===selected),currentEntry=store.entries.find(e=>e.id===selected),currentNotice=store.notices.find(n=>n.id===selected);
 const openEntry=(type:EntryType='Expense',id?:string)=>{setEntryType(type);setEntryAgreement(id||store.agreements[0]?.id||'');setEntryAmount('');setEntryRef('');setEntryDesc('');setEntryDate(today);setEntryCategory(type==='Expense'?'Repair':type==='Salary advance'?'Advance':'Rent');setEntryPayer(type==='Customer payment'?store.agreements.find(a=>a.id===(id||store.agreements[0]?.id))?.customer||'Customer':'Operator');setEntryLiable(type==='Expense'?'Owner':'Operator');setEntryOffset(true);setEntryReceipt('');setEntryError('');setEntryKey(crypto.randomUUID());setEntryOpen(true)};
 const chosen=store.agreements.find(a=>a.id===entryAgreement);const amount=Math.round(Number(entryAmount));const repeated=store.entries.some(e=>e.status!=='Reversed'&&entryRef.trim()&&e.reference.toLowerCase()===entryRef.trim().toLowerCase());
 const submitEntry=()=>{if(!chosen){setEntryError('Choose an agreement.');return}if(store.closed.includes(chosen.id)){setEntryError('This agreement is closed for September. Reopen policy is not enabled in this demo.');return}if(!Number.isSafeInteger(Number(entryAmount))||amount<=0){setEntryError('Enter a whole BDT amount greater than zero.');return}if(!entryRef.trim()){setEntryError('Add a transaction or document reference.');return}if(repeated){setEntryError('This reference is already recorded. Check the existing entry before submitting.');return}if(entryType==='Customer payment'&&amount>statement(chosen,store.entries).customerDue){setEntryError('Payment exceeds the open rent balance in this demo.');return}if(entryType==='Owner payout'&&amount>statement(chosen,store.entries).ownerDue){setEntryError('Payout exceeds the current owner balance.');return}if((entryType==='Driver payout'||entryType==='Salary advance')&&amount>statement(chosen,store.entries).driverDue){setEntryError('Amount exceeds the current driver balance.');return}
 if(apiMode){const backend=store.backend;if(!backend){setEntryError('The backend is not connected. Sign in and reload.');return}const periodId=backend.periodIds[chosen.id];const ob=backend.obligationIds[chosen.id];if(!periodId||!ob){setEntryError('Issue the September period before recording an entry.');return}setApiBusy(true);void (async()=>{try{let response;if(entryType==='Expense'){const categories:{[key:string]:string}={Repair:'repair',Fuel:'fuel','Toll / parking':'toll',Maintenance:'maintenance',Cleaning:'cleaning',Other:'other'};const category=categories[entryCategory];if(!category)throw new Error('Choose a supported expense category.');response=await livePost(backend.orgId,'/expenses',{period_id:periodId,category,amount:String(amount),event_date:entryDate,paid_by:entryPayer.toLowerCase(),responsible:entryLiable.toLowerCase(),offset_owner:entryOffset&&chosen.rules.offset&&entryPayer==='Operator'&&entryLiable==='Owner',reference:entryRef,description:entryDesc},entryKey)}else{const kinds:{[key:string]:string}={'Customer payment':'customer_payment','Owner payout':'owner_payout','Driver payout':'driver_payout','Salary advance':'salary_advance'};const kind=kinds[entryType];const obligationId=entryType==='Customer payment'?ob.customer:entryType==='Owner payout'?ob.owner:ob.driver;response=await livePost(backend.orgId,'/payments',{kind,amount:String(amount),reference:entryRef,method:'bank',event_date:entryDate,allocations:[{obligation_id:obligationId,amount:String(amount)}]},entryKey)}const next=await refreshLive();setEntryOpen(false);setSelected(next.entries.find(x=>x.reference===entryRef)?.id||null);setToast('Entry saved to the Django backend. Message delivery remains queued.')}catch(e){setEntryError((e as Error).message)}finally{setApiBusy(false)}})();return}
 const item:Entry={id:'ENT-'+(2401+store.entries.length),agreementId:chosen.id,type:entryType,amount,date:entryDate,category:entryCategory,paidBy:entryType==='Customer payment'?chosen.customer:entryPayer,responsible:entryType==='Expense'?entryLiable:'Operator',reference:entryRef.trim(),description:entryDesc.trim()||entryCategory+' · '+chosen.vehicle,status:entryType==='Expense'&&amount>=5000?'Pending approval':'Posted',offset:entryType==='Expense'&&entryLiable==='Owner'&&entryPayer==='Operator'&&entryOffset&&chosen.rules.offset,receipt:entryReceipt||undefined};
 setStore(s=>({...s,entries:[item,...s.entries],notices:[{id:'NT-'+Date.now(),title:item.status==='Posted'?'Entry recorded':'Expense awaiting approval',detail:item.id+' · '+chosen.vehicle,date:entryDate,status:'Queued',read:false,recipient:entryType==='Customer payment'?'Customer billing contact':entryType==='Expense'?entryLiable:'Affected party'},...s.notices]}));setEntryOpen(false);setSelected(item.id);setToast(item.status==='Posted'?`${item.id} posted in this demo. Message queued.`:`${item.id} saved for approval. Balances unchanged.`)};
 const approve=(id:string)=>{if(apiMode){const backend=store.backend;const expenseId=backend?.expenseIds[id];if(!backend||!expenseId)return;void livePost(backend.orgId,`/expenses/${expenseId}/approve`,{}).then(refreshLive).then(()=>{setSelected(null);setToast(id+' approved.')}).catch(e=>setToast(e.message));return}setStore(s=>({...s,entries:s.entries.map(e=>e.id===id?{...e,status:'Posted'}:e)}));setToast(id+' approved and reflected in balances.');setSelected(null)};
 const reverse=(id:string)=>{if(apiMode){const backend=store.backend;const expenseId=backend?.expenseIds[id];if(!backend||!expenseId)return;const reason=window.prompt('Why is this posted entry being reversed?');if(!reason?.trim())return;void livePost(backend.orgId,`/expenses/${expenseId}/reverse`,{reason:reason.trim()}).then(refreshLive).then(()=>{setSelected(null);setToast(id+' reversed.')}).catch(e=>setToast(e.message));return}setStore(s=>({...s,entries:s.entries.map(e=>e.id===id?{...e,status:'Reversed'}:e)}));setToast(id+' reversed in this demo.');setSelected(null)};
 const closeSettlement=(id:string)=>{if(apiMode){const backend=store.backend;const periodId=backend?.periodIds[id];if(!backend||!periodId)return;void livePost(backend.orgId,`/periods/${periodId}/close`,{}).then(refreshLive).then(()=>{setConfirmClose(null);setToast(id+' closed in the backend.')}).catch(e=>{setConfirmClose(null);setToast(e.message)});return}setStore(s=>({...s,closed:[...new Set([...s.closed,id])]}));setConfirmClose(null);setToast(id+' closed for September. This demo records the state locally.')};
 const createAgreement=()=>{const n=newAgreement;if(!n.customer.trim()||!n.vehicle.trim()||!n.registration.trim()||!n.owner.trim()||!n.driver.trim()||![n.rent,n.ownerRent,n.salary].every(x=>Number.isSafeInteger(Number(x))&&Number(x)>0)){setWizardError('Complete all parties, vehicle details and positive whole BDT amounts.');return}if(store.agreements.some(a=>a.registration.toLowerCase()===n.registration.toLowerCase()&&a.status==='Active')){setWizardError('This registration already has an active agreement.');return}if(apiMode){if(n.start>'2026-09-30'){setWizardError('This prototype displays September 2026. Choose an effective date in or before September.');return}const backend=store.backend;if(!backend){setWizardError('Backend session is unavailable.');return}setApiBusy(true);void (async()=>{try{const a=await livePost(backend.orgId,'/agreements/quick',{customer:n.customer,owner:n.owner,driver:n.driver,vehicle:n.vehicle,registration:n.registration,start:n.start,rent:n.rent,owner_rent:n.ownerRent,salary:n.salary,fuel:n.fuel,repair:n.repair,offset:n.offset});await livePost(backend.orgId,`/agreements/${a.id}/periods?month=2026-09-01`,{});await refreshLive();setAgreementOpen(false);setWizardStep(0);setSelected(`AGR-${a.id}`);setToast('Agreement and September obligations created in the backend.')}catch(e){setWizardError((e as Error).message)}finally{setApiBusy(false)}})();return}const a:Agreement={id:'AGR-'+(1042+store.agreements.length),vehicle:n.vehicle,registration:n.registration,owner:n.owner,customer:n.customer,driver:n.driver,rent:Number(n.rent),ownerRent:Number(n.ownerRent),salary:Number(n.salary),start:n.start,status:'Active',rules:{fuel:n.fuel,repair:n.repair,offset:n.offset}};setStore(s=>({...s,agreements:[...s.agreements,a]}));setAgreementOpen(false);setWizardStep(0);setWizardError('');setSelected(a.id);setToast(a.id+' added to this demo.')};
 const exportEntries=()=>csv([['ID','Agreement','Date','Type','Amount BDT','Paid by','Responsible','Status','Reference'],...store.entries.filter(e=>statusFilter==='All'||e.status===statusFilter).map(e=>[e.id,e.agreementId,e.date,e.type,e.amount,e.paidBy,e.responsible,e.status,e.reference])],`rentflow-entries-${period}.csv`);
 const exportReport=()=>{const config=reportConfig(reportType);csv([['Agreement','Vehicle',config.party,...config.columns.map(c=>c+' BDT'),'Generated at'],...related.map(a=>{const s=statement(a,store.entries);return[a.id,a.registration,config.party==='Owner'?a.owner:config.party==='Driver'?a.driver:a.customer,...config.values(a,s),new Date().toISOString()]})],`rentflow-${reportType.toLowerCase().replaceAll(' ','-')}-${period}.csv`)};
 const tableFilter=<div className="toolbar"><div className="filter-icon"><Filter size={16}/></div><Select value={ownerFilter} onValueChange={changeOwner}><SelectTrigger aria-label="Filter by owner"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="All owners">All owners</SelectItem>{[...new Set(store.agreements.map(a=>a.owner))].map(o=><SelectItem key={o} value={o}>{o}</SelectItem>)}</SelectContent></Select><Select value={statusFilter} onValueChange={changeStatus}><SelectTrigger aria-label="Filter by status"><SelectValue/></SelectTrigger><SelectContent>{['All','Posted','Pending approval','Reversed'].map(s=><SelectItem key={s} value={s}>{s}</SelectItem>)}</SelectContent></Select></div>;
 const metrics=[{label:'Customer outstanding',value:financial.customer,icon:ArrowDownLeft,detail:'Billed rent less receipts',color:'blue'},{label:'Owners payable',value:financial.owner,icon:ArrowUpRight,detail:'Net of permitted offsets',color:'gold'},{label:'Drivers payable',value:financial.driver,icon:WalletCards,detail:'Earned less payouts',color:'purple'},{label:'Cash movement',value:financial.cash,icon:Banknote,detail:'Recorded inflows less outflows',color:'gray'}];
 return <div className="app-shell">
  <aside className={'sidebar '+(mobileMenu?'mobile-open':'')}><div className="brand"><div className="brand-mark"><CarFront size={23}/></div><div><strong>RentFlow</strong><span>OPERATIONS</span></div><button aria-label="Close menu" className="mobile-close" onClick={()=>setMobileMenu(false)}><X size={20}/></button></div><div className="workspace"><div className="workspace-icon">R</div><div><strong>RentFlow HQ</strong><small>Dhaka · Main branch</small></div><ChevronRight size={16}/></div><nav aria-label="Main navigation">{nav.map(([group,name,Icon],i)=><div key={name}>{group&&<div className="nav-group">{group}</div>}<button className={'nav-link '+(page===name?'active':'')} onClick={()=>navigate(name)}><Icon size={18}/><span>{name}</span>{name==='Notifications'&&store.notices.some(n=>!n.read)&&<i className="nav-dot"/>}</button></div>)}</nav><div className="sidebar-foot"><button onClick={()=>navigate('Actor portal')}><UsersRound size={17}/> Actor portal preview <ChevronRight size={15}/></button><div className="demo-sidebar">{apiMode?'API WORKSPACE':'DEMO WORKSPACE'}<br/><span>{apiMode?'Django backend · September 2026':'Sample data · saved in this browser'}</span></div></div></aside>
  <div className="main-shell"><header className="topbar"><button className="menu-button" onClick={()=>setMobileMenu(true)} aria-label="Open menu"><Menu size={22}/></button><div className="breadcrumb">Workspace <ChevronRight size={14}/> <strong>{page}</strong></div><div className="top-actions"><div className="global-search"><Search size={17}/><Input aria-label="Search agreements, people or vehicles" placeholder="Search agreement, car, person..." value={search} onChange={e=>changeSearch(e.target.value)}/><kbd>⌕</kbd></div><button className="icon-button" aria-label="View notifications" onClick={()=>navigate('Notifications')}><Bell size={19}/>{store.notices.some(n=>!n.read)&&<i/>}</button><span className="top-divider"/><button className="profile" onClick={()=>navigate('Settings')} aria-label="Open settings"><span>SH</span><div><strong>{apiMode?store.backend?.userName||'Accountant':'Sakib Haider'}</strong><small>{apiMode?'Django session':'Administrator'}</small></div></button></div></header>
   <main className="content"><div className="page-intro"><div><div className="eyebrow">RENTFLOW / {page.toUpperCase()}</div><h1>{page==='Overview'?`Good morning, ${apiMode?store.backend?.userName||'there':'Sakib'}`:page}</h1><p>{page==='Overview'?'Here is where your rental accounts stand this month.':page==='Settlements'?'Review every balance before closing the month.':page==='Actor portal'?'See the limited view each party receives.':page==='Reports'?'Explore account totals and export the current scope.':page==='Settings'?'Policies and demo workspace controls.':'September 2026 · Main branch'}</p></div><div className="intro-actions"><div className="period-chip"><CalendarDays size={16}/> September 2026</div>{page!=='Actor portal'&&<Button onClick={()=>openEntry()} className="primary-action"><Plus size={17}/> Record entry</Button>}</div></div>
   <div className="demo-banner"><Info size={17}/><span>{apiMode?<><strong>API mode.</strong> Entries use Django and PostgreSQL. Notifications and the actor preview still need production delivery and identity wiring.</>:<><strong>Interactive demo.</strong> Sample agreements and entries; changes stay in this browser. No live payments, messages, or accounting posts occur.</>}</span></div>{apiError&&<div className="form-error" role="alert">Backend connection: {apiError}. Sign in at the Django admin, then reload this page.</div>}
   {page==='Overview'&&<><div className="metric-grid">{metrics.map(m=><Card key={m.label} className="metric"><div className="metric-top"><span>{m.label}</span><span className={'metric-icon '+m.color}><m.icon size={19}/></span></div><strong className="nums">{money(m.value)}</strong><small>{m.detail}</small></Card>)}</div><div className="overview-layout"><div className="overview-main"><Card><SectionHeading title="Monthly account overview" subtitle="Each row connects customer, owner and driver balances." action={<button className="text-button" onClick={()=>navigate('Settlements')}>View settlements <ChevronRight size={16}/></button>}/><AccountTable agreements={related} store={store} onSelect={setSelected} sort={sort} setSort={setSort}/></Card><Card><SectionHeading title="Recent activity" subtitle="Entries link back to their source account." action={<button className="text-button" onClick={()=>navigate('Cashbook')}>Cashbook <ChevronRight size={16}/></button>}/><div className="activity-list">{store.entries.slice(0,5).map(e=>{const a=store.agreements.find(a=>a.id===e.agreementId);return <button className="activity" key={e.id} onClick={()=>setSelected(e.id)}><span className={'activity-icon '+(e.type==='Customer payment'?'incoming':'outgoing')}>{e.type==='Customer payment'?<ArrowDownLeft size={18}/>:<ArrowUpRight size={18}/>}</span><span className="activity-title"><strong>{e.description}</strong><small>{a?.vehicle} · {fmtDate(e.date)} · {e.id}</small></span><b className="nums">{money(e.amount)}</b><ChevronRight size={15}/></button>})}</div></Card></div><div className="overview-aside"><Card className="attention-card"><SectionHeading title="Needs attention" subtitle="Resolve these before month close."/><div className="attention-list"><button onClick={()=>navigate('Expenses')}><span className="attention-symbol amber"><Clock3 size={18}/></span><span><strong>{store.entries.filter(e=>e.status==='Pending approval').length} pending expense</strong><small>Review responsibility and proof</small></span><ChevronRight size={16}/></button><button onClick={()=>navigate('Notifications')}><span className="attention-symbol red"><AlertCircle size={18}/></span><span><strong>{store.notices.filter(n=>n.status==='Failed').length} failed message</strong><small>Check recipient and retry</small></span><ChevronRight size={16}/></button><button onClick={()=>navigate('Settlements')}><span className="attention-symbol teal"><Layers3 size={18}/></span><span><strong>{store.agreements.length-store.closed.length} open settlements</strong><small>September 2026</small></span><ChevronRight size={16}/></button></div></Card><Card className="quick-card"><SectionHeading title="Quick actions"/><div className="quick-actions"><button onClick={()=>openEntry('Expense')}><ReceiptText size={18}/> Record expense <Plus size={16}/></button><button onClick={()=>openEntry('Customer payment')}><ArrowDownLeft size={18}/> Receive payment <Plus size={16}/></button><button onClick={()=>{setWizardStep(0);setAgreementOpen(true)}}><FileSignature size={18}/> New agreement <Plus size={16}/></button></div></Card><Card className="insight-card"><div className="insight-label"><ChartNoAxesCombined size={17}/> ACCRUAL SNAPSHOT</div><strong className="nums">{money(financial.margin)}</strong><p>Estimated margin before tax and other unrecorded costs. Cash movement is shown separately.</p></Card></div></div></>}
   {page==='Agreements'&&<Card><SectionHeading title="Rental agreements" subtitle={`${related.length} visible · monthly contracts`} action={<Button onClick={()=>{setWizardStep(0);setAgreementOpen(true)}}><Plus size={16}/> New agreement</Button>}/>{tableFilter}<Table><TableHeader><TableRow><TableHead>Agreement / car</TableHead><TableHead>Customer</TableHead><TableHead>Owner · driver</TableHead><TableHead className="text-right">Customer rent</TableHead><TableHead>Status</TableHead><TableHead/></TableRow></TableHeader><TableBody>{related.map(a=><TableRow key={a.id} className="click-row" onClick={()=>setSelected(a.id)}><TableCell><b>{a.id}</b><small>{a.vehicle} · {a.registration}</small></TableCell><TableCell>{a.customer}</TableCell><TableCell>{a.owner}<small>{a.driver}</small></TableCell><TableCell className="text-right nums">{money(a.rent)}</TableCell><TableCell><Badge tone="good">{a.status}</Badge></TableCell><TableCell><button className="row-link" aria-label={'Open '+a.id}><ChevronRight size={18}/></button></TableCell></TableRow>)}</TableBody></Table>{related.length===0&&<Empty text="No agreements match this search. Clear your filters to see all accounts."/>}</Card>}
   {page==='Vehicles'&&<Card><SectionHeading title="Fleet and assignments" subtitle="Owner, customer and driver relationships are shown together."/><div className="vehicle-grid">{related.map(a=>{const s=statement(a,store.entries);return <button className="vehicle-card" key={a.id} onClick={()=>setSelected(a.id)}><div className="vehicle-card-top"><span className="vehicle-art"><CarFront size={27}/></span><Badge tone="good">Assigned</Badge></div><strong>{a.vehicle}</strong><small>{a.registration}</small><div className="vehicle-divider"/><div><span>Owner</span><b>{a.owner}</b></div><div><span>Customer</span><b>{a.customer}</b></div><div><span>Driver</span><b>{a.driver}</b></div><div className="vehicle-foot"><span>Customer due <b className="nums">{money(s.customerDue)}</b></span><ChevronRight size={18}/></div></button>})}</div>{related.length===0&&<Empty text="No vehicles match the search."/>}</Card>}
   {(['Customers','Owners','Drivers'] as Page[]).includes(page)&&<Card><SectionHeading title={page+' accounts'} subtitle="Select a person to inspect the related agreement and statement."/><Table><TableHeader><TableRow><TableHead>{page.slice(0,-1)}</TableHead><TableHead>Vehicle / agreement</TableHead><TableHead className="text-right">{page==='Customers'?'Billed rent':page==='Owners'?'Gross entitlement':'Salary earned'}</TableHead><TableHead className="text-right">{page==='Customers'?'Outstanding':'Amount due'}</TableHead><TableHead/></TableRow></TableHeader><TableBody>{related.map(a=>{const s=statement(a,store.entries);return <TableRow key={a.id} className="click-row" onClick={()=>setSelected(a.id)}><TableCell><b>{page==='Customers'?a.customer:page==='Owners'?a.owner:a.driver}</b></TableCell><TableCell>{a.vehicle}<small>{a.id}</small></TableCell><TableCell className="text-right nums">{money(page==='Customers'?a.rent:page==='Owners'?a.ownerRent:a.salary)}</TableCell><TableCell className="text-right nums due">{money(page==='Customers'?s.customerDue:page==='Owners'?s.ownerDue:s.driverDue)}</TableCell><TableCell><ChevronRight size={18}/></TableCell></TableRow>})}</TableBody></Table>{related.length===0&&<Empty text="No matching accounts."/>}</Card>}
   {page==='Expenses'&&<Card><SectionHeading title="Expenses and maintenance" subtitle="Payer and ultimately responsible party are recorded separately." action={<Button onClick={()=>openEntry('Expense')}><Plus size={16}/> Record expense</Button>}/>{tableFilter}<EntryTable entries={store.entries.filter(e=>e.type==='Expense'&&((statusFilter==='All')||e.status===statusFilter)&&related.some(a=>a.id===e.agreementId))} store={store} onSelect={setSelected}/></Card>}
   {page==='Billing'&&<><div className="mini-metrics"><Card><span>Total billed</span><strong>{money(related.reduce((s,a)=>s+a.rent,0))}</strong></Card><Card><span>Received</span><strong>{money(related.reduce((s,a)=>s+statement(a,store.entries).received,0))}</strong></Card><Card><span>Outstanding</span><strong>{money(related.reduce((s,a)=>s+statement(a,store.entries).customerDue,0))}</strong></Card></div><Card><SectionHeading title="Customer billing and collections" subtitle="Partial receipts reduce each agreement's open rent balance." action={<Button onClick={()=>openEntry('Customer payment')}><Plus size={16}/> Receive payment</Button>}/><AccountTable agreements={related} store={store} onSelect={setSelected} sort={sort} setSort={setSort}/></Card></>}
   {page==='Owner payables'&&<Card><SectionHeading title="Owner payables" subtitle="Gross rent less authorized offsets and transfers." action={<Button onClick={()=>openEntry('Owner payout')}><Plus size={16}/> Record payout</Button>}/><Table><TableHeader><TableRow><TableHead>Owner / car</TableHead><TableHead className="text-right">Gross</TableHead><TableHead className="text-right">Offsets</TableHead><TableHead className="text-right">Net payable</TableHead><TableHead className="text-right">Paid</TableHead><TableHead className="text-right">Due</TableHead><TableHead/></TableRow></TableHeader><TableBody>{related.map(a=>{const s=statement(a,store.entries);return <TableRow className="click-row" key={a.id} onClick={()=>setSelected(a.id)}><TableCell><b>{a.owner}</b><small>{a.vehicle} · {a.id}</small></TableCell><TableCell className="text-right nums">{money(s.ownerGross)}</TableCell><TableCell className="text-right nums">{money(s.offsets)}</TableCell><TableCell className="text-right nums">{money(s.ownerNet)}</TableCell><TableCell className="text-right nums">{money(s.ownerPaid)}</TableCell><TableCell className="text-right nums due">{money(s.ownerDue)}</TableCell><TableCell><ChevronRight size={18}/></TableCell></TableRow>})}</TableBody></Table></Card>}
   {page==='Payroll'&&<Card><SectionHeading title="Driver pay and advances" subtitle="Only salary, advances and payouts are shown here." action={<Button onClick={()=>openEntry('Driver payout')}><Plus size={16}/> Record payout</Button>}/><Table><TableHeader><TableRow><TableHead>Driver / car</TableHead><TableHead className="text-right">Earned</TableHead><TableHead className="text-right">Advance</TableHead><TableHead className="text-right">Paid</TableHead><TableHead className="text-right">Due</TableHead><TableHead/></TableRow></TableHeader><TableBody>{related.map(a=>{const s=statement(a,store.entries);return <TableRow className="click-row" key={a.id} onClick={()=>setSelected(a.id)}><TableCell><b>{a.driver}</b><small>{a.vehicle} · {a.id}</small></TableCell><TableCell className="text-right nums">{money(s.driverEarned)}</TableCell><TableCell className="text-right nums">{money(s.advance)}</TableCell><TableCell className="text-right nums">{money(s.driverPaid)}</TableCell><TableCell className="text-right nums due">{money(s.driverDue)}</TableCell><TableCell><ChevronRight size={18}/></TableCell></TableRow>})}</TableBody></Table><div className="under-table"><button className="text-button" onClick={()=>openEntry('Salary advance')}>Record a salary advance <ArrowUpRight size={15}/></button></div></Card>}
   {page==='Settlements'&&<><div className="settlement-banner"><div><span className="eyebrow">SEPTEMBER 2026 · CLOSE PERIOD</span><h2>Month-end settlement</h2><p>Review customer, owner, driver and operator positions for each agreement.</p></div><div className="settlement-count"><strong>{store.closed.length}/{store.agreements.length}</strong><span>closed</span></div></div><div className="settlement-grid">{related.map(a=>{const s=statement(a,store.entries),pending=store.entries.some(e=>e.agreementId===a.id&&e.status==='Pending approval'),closed=store.closed.includes(a.id);return <Card key={a.id} className="settlement-card"><div className="settlement-top"><div><small>{a.id} · {a.registration}</small><h3>{a.customer}</h3></div><Badge tone={closed?'good':pending?'warn':'blue'}>{closed?'Closed':pending?'Needs review':'Ready to review'}</Badge></div><div className="settlement-figures"><div><span>Customer due</span><b>{money(s.customerDue)}</b></div><div><span>Owner due</span><b>{money(s.ownerDue)}</b></div><div><span>Driver due</span><b>{money(s.driverDue)}</b></div></div>{pending&&<p className="inline-alert"><AlertCircle size={15}/> Expense approval required before closing.</p>}<div className="settlement-actions"><button className="text-button" onClick={()=>setSelected(a.id)}>View four statements <ChevronRight size={15}/></button><Button variant="outline" size="sm" disabled={closed||pending} onClick={()=>setConfirmClose(a.id)}>{closed?'Closed':'Close'}</Button></div></Card>})}</div></>}
   {page==='Cashbook'&&<Card><SectionHeading title="Cashbook and entries" subtitle="Recorded receipts, expenses, advances and payouts." action={<Button variant="outline" onClick={exportEntries}><Download size={16}/> Export CSV</Button>}/>{tableFilter}<EntryTable entries={store.entries.filter(e=>(statusFilter==='All'||e.status===statusFilter)&&related.some(a=>a.id===e.agreementId))} store={store} onSelect={setSelected}/></Card>}
   {page==='Reports'&&<><div className="report-header"><Card><span className="eyebrow">REPORT BUILDER</span><h2>September account summary</h2><p>Select a report and apply the owner filter. Export a scoped CSV with source totals.</p><div className="report-controls"><Select value={reportType} onValueChange={setReportType}><SelectTrigger aria-label="Report type"><SelectValue/></SelectTrigger><SelectContent>{['Vehicle contribution','Customer balances','Owner liability','Driver payroll','Cash movement'].map(r=><SelectItem key={r} value={r}>{r}</SelectItem>)}</SelectContent></Select><Select value={ownerFilter} onValueChange={changeOwner}><SelectTrigger aria-label="Filter report by owner"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="All owners">All owners</SelectItem>{[...new Set(store.agreements.map(a=>a.owner))].map(o=><SelectItem key={o} value={o}>{o}</SelectItem>)}</SelectContent></Select><Button onClick={exportReport}><FileDown size={16}/> Download CSV</Button></div></Card></div><Card><SectionHeading title={reportType} subtitle={`${related.length} agreements · generated from current demo entries`}/><ReportTable type={reportType} agreements={related} store={store} onSelect={setSelected}/></Card></>}
   {page==='Notifications'&&<Card><SectionHeading title="Notification activity" subtitle="Delivery status is distinct from posting state."/><div className="notice-list">{store.notices.map(n=><button className={'notice '+(!n.read?'unread':'')} key={n.id} onClick={()=>{setStore(s=>({...s,notices:s.notices.map(x=>x.id===n.id?{...x,read:true}:x)}));setSelected(n.id)}}><span className={'notice-symbol '+(n.status==='Failed'?'red':'teal')}><Bell size={18}/></span><span><strong>{n.title}</strong><small>{n.detail} · {n.recipient}</small></span><span className="notice-end"><Badge tone={n.status==='Failed'?'bad':n.status==='Delivered'?'good':'warn'}>{n.status}</Badge><small>{fmtDate(n.date)}</small></span><ChevronRight size={17}/></button>)}</div></Card>}
   {page==='Settings'&&<div className="settings-grid"><Card><SectionHeading title="Workspace policies"/><div className="policy-row"><span>Currency</span><b>BDT · whole taka in demo</b></div><div className="policy-row"><span>Expense approval</span><b>From ৳5,000</b></div><div className="policy-row"><span>Owner repair offset</span><b>Per agreement</b></div><div className="policy-row"><span>Billing cadence</span><b>Monthly</b></div><div className="policy-row"><span>Message delivery</span><b>Simulated queue</b></div></Card><Card><SectionHeading title={apiMode?"Backend workspace":"Demo data"} subtitle={apiMode?"PostgreSQL stores entries and agreements.":"Changes are saved to your browser only."}/><p className="settings-copy">{apiMode?"Reset is available only in demo mode. Manage production data through authorized workflows.":"Reset restores the four sample agreements and worked September entries. This cannot affect real accounts."}</p><Button variant="outline" disabled={apiMode} onClick={()=>{if(window.confirm('Reset all local demo changes?')){setStore(structuredClone(seed));setToast('Demo workspace restored.')}}}><RotateCcw size={16}/> Reset sample data</Button></Card></div>}
   {page==='Actor portal'&&<div className="actor-layout"><Card className="actor-configuration"><SectionHeading title="Preview an actor account" subtitle="Choose a role and party to inspect their limited view."/><div className="role-choices">{(['Owner','Driver','Customer'] as const).map(x=><button key={x} className={role===x?'chosen':''} onClick={()=>{setRole(x);setActor(x==='Owner'?store.agreements[0]?.owner||'':x==='Driver'?store.agreements[0]?.driver||'':store.agreements[0]?.customer||'')}}>{x}</button>)}</div><label className="field-label" htmlFor="actor-select">Account</label><Select value={actor} onValueChange={setActor}><SelectTrigger id="actor-select" className="w-full"><SelectValue/></SelectTrigger><SelectContent>{[...new Set(store.agreements.map(a=>role==='Owner'?a.owner:role==='Driver'?a.driver:a.customer))].map(x=><SelectItem value={x} key={x}>{x}</SelectItem>)}</SelectContent></Select><p className="actor-helper">Preview only. A production portal needs server verified identity and record scope.</p></Card><div className="phone-frame"><div className="phone-head"><span>RentFlow</span><span>9:41 ◉</span></div><div className="phone-content"><div className="phone-greeting">SEPTEMBER 2026<h2>Hello, {actor.split(' ')[0]}</h2><p>Your account at a glance</p></div>{store.agreements.filter(a=>role==='Owner'?a.owner===actor:role==='Driver'?a.driver===actor:a.customer===actor).map(a=>{const s=statement(a,store.entries);const due=role==='Owner'?s.ownerDue:role==='Driver'?s.driverDue:s.customerDue;return <div className="phone-card" key={a.id}><div className="phone-card-head"><CarFront size={20}/><span>{a.vehicle}</span></div><small>{a.registration}</small><div className="phone-due"><span>{role==='Customer'?'Your outstanding':'Due to you'}</span><strong>{money(due)}</strong></div><div className="phone-lines"><div><span>{role==='Customer'?'Billed':role==='Owner'?'Net entitlement':'Earned salary'}</span><b>{money(role==='Customer'?a.rent:role==='Owner'?s.ownerNet:s.driverEarned)}</b></div><div><span>{role==='Customer'?'Paid':role==='Owner'?'Transferred':'Paid / advanced'}</span><b>{money(role==='Customer'?s.received:role==='Owner'?s.ownerPaid:s.driverPaid+s.advance)}</b></div></div></div>})}<div className="phone-nav"><span>⌂<small>Home</small></span><span>▤<small>Statement</small></span><span>◫<small>Messages</small></span></div></div></div></div>}
   </main></div>
   <Sheet open={!!selected} onOpenChange={o=>!o&&setSelected(null)}><SheetContent className="detail-sheet"><SheetHeader><SheetTitle>{current?current.vehicle:currentEntry?currentEntry.id:currentNotice?'Message detail':'Detail'}</SheetTitle><SheetDescription>{current?current.id+' · '+current.registration:currentEntry?currentEntry.type+' · '+fmtDate(currentEntry.date):currentNotice?.recipient}</SheetDescription></SheetHeader>{current&&<div className="sheet-scroll"><div className="detail-relations"><div><span>Customer</span><b>{current.customer}</b></div><div><span>Owner</span><b>{current.owner}</b></div><div><span>Driver</span><b>{current.driver}</b></div></div><Tabs defaultValue="customer"><TabsList className="detail-tabs"><TabsTrigger value="customer">Customer</TabsTrigger><TabsTrigger value="owner">Owner</TabsTrigger><TabsTrigger value="driver">Driver</TabsTrigger><TabsTrigger value="operator">Operator</TabsTrigger><TabsTrigger value="terms">Terms</TabsTrigger></TabsList>{(['customer','owner','driver','operator'] as const).map(tab=>{const s=statement(current,store.entries);const lines=tab==='customer'?[['Monthly rent',current.rent],['Receipts',-s.received],['Outstanding',s.customerDue]]:tab==='owner'?[['Gross owner rent',s.ownerGross],['Authorized offsets',-s.offsets],['Net payable',s.ownerNet],['Already paid',-s.ownerPaid],['Due to owner',s.ownerDue]]:tab==='driver'?[['Salary earned',s.driverEarned],['Advances',-s.advance],['Already paid',-s.driverPaid],['Due to driver',s.driverDue]]:[['Earned rent',current.rent],['Owner obligation',-current.ownerRent],['Driver obligation',-current.salary],['Operator costs',-s.operatorCosts],['Accrual margin',s.margin],['Actual cash movement',s.cash]];return <TabsContent value={tab} key={tab}><div className="statement-lines">{lines.map(([label,value],i)=><div className={i===lines.length-1?'statement-total':''} key={label}><span>{label}</span><b className="nums">{Number(value)<0?'−':''}{money(Number(value))}</b></div>)}</div>{tab==='operator'&&<p className="note">Accrual margin uses earned rent. Cash movement uses only recorded receipts and payments.</p>}{tab==='owner'&&<p className="note">Only operator funded owner costs with an authorized offset reduce this payable.</p>}</TabsContent>})}<TabsContent value="terms"><div className="terms"><div><span>Started</span><b>{fmtDate(current.start)}</b></div><div><span>Fuel responsibility</span><b>{current.rules.fuel}</b></div><div><span>Repair responsibility</span><b>{current.rules.repair}</b></div><div><span>Owner offsets</span><b>{current.rules.offset?'Permitted for owner costs':'Separate reimbursement'}</b></div></div></TabsContent></Tabs><h3 className="detail-subheading">Source entries</h3><div className="source-list">{store.entries.filter(e=>e.agreementId===current.id).map(e=><button key={e.id} onClick={()=>setSelected(e.id)}><span><b>{e.description}</b><small>{e.id} · {fmtDate(e.date)} · {e.status}</small></span><b>{money(e.amount)}</b><ChevronRight size={15}/></button>)}</div><div className="sheet-footer"><Button variant="outline" onClick={()=>{setSelected(null);openEntry('Customer payment',current.id)}}>Receive payment</Button><Button onClick={()=>{setSelected(null);openEntry('Expense',current.id)}}>Record expense</Button></div></div>}{currentEntry&&<div className="sheet-scroll"><div className="entry-amount">{money(currentEntry.amount)} <Badge tone={currentEntry.status==='Posted'?'good':currentEntry.status==='Reversed'?'bad':'warn'}>{currentEntry.status}</Badge></div><div className="terms">{[['Agreement',currentEntry.agreementId],['Service date',fmtDate(currentEntry.date)],['Category',currentEntry.category],['Paid by',currentEntry.paidBy],['Responsible',currentEntry.responsible],['Reference',currentEntry.reference],['Receipt',currentEntry.receipt||'None attached'],['Owner offset',currentEntry.offset?'Authorized':'No']].map(([k,v])=><div key={k}><span>{k}</span><b>{v}</b></div>)}</div><p className="entry-description">{currentEntry.description}</p><p className="note">{currentEntry.status==='Pending approval'?'Pending entries do not change balances.':'This source contributes to the relevant account statement.'}</p><div className="sheet-footer">{currentEntry.status==='Pending approval'&&<Button onClick={()=>approve(currentEntry.id)}><CheckCircle2 size={16}/> Approve</Button>}{currentEntry.status==='Posted'&&<Button variant="outline" onClick={()=>{if(apiMode||confirm('Reverse this posted demo entry?'))reverse(currentEntry.id)}}><RotateCcw size={16}/> Reverse entry</Button>}<Button variant="outline" onClick={()=>setSelected(currentEntry.agreementId)}>View agreement</Button></div></div>}{currentNotice&&<div className="sheet-scroll"><div className="terms"><div><span>Recipient</span><b>{currentNotice.recipient}</b></div><div><span>Status</span><Badge tone={currentNotice.status==='Failed'?'bad':currentNotice.status==='Delivered'?'good':'warn'}>{currentNotice.status}</Badge></div><div><span>Date</span><b>{fmtDate(currentNotice.date)}</b></div><div><span>Source</span><b>{currentNotice.detail}</b></div></div><p className="note">Delivery states are simulated for this demo; no message has been sent.</p>{currentNotice.status==='Failed'&&<Button onClick={()=>{if(apiMode&&store.backend){const org=store.backend.orgId;void livePost(org,`/notifications/${currentNotice.id.replace('NT-','')}/retry`,{}).then(refreshLive).then(()=>{setToast('Retry queued in the backend.');setSelected(null)}).catch(e=>setToast(e.message));return}setStore(s=>({...s,notices:s.notices.map(n=>n.id===currentNotice.id?{...n,status:'Queued'}:n)}));setToast('Retry queued in this demo.');setSelected(null)}}><RefreshCcw size={16}/> Retry delivery</Button>}</div>}</SheetContent></Sheet>
   <Dialog open={entryOpen} onOpenChange={setEntryOpen}><DialogContent className="entry-dialog"><DialogHeader><DialogTitle>Record financial entry</DialogTitle><DialogDescription>Review who paid, who owes and the effect on balances.</DialogDescription></DialogHeader><div className="entry-form"><div className="form-grid"><label>Entry type<Select value={entryType} onValueChange={v=>{setEntryType(v as EntryType);setEntryError('');setEntryCategory(v==='Expense'?'Repair':'Rent');setEntryPayer(v==='Customer payment'?chosen?.customer||'Customer':'Operator')}}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{(['Expense','Customer payment','Owner payout','Driver payout','Salary advance'] as EntryType[]).map(x=><SelectItem value={x} key={x}>{x}</SelectItem>)}</SelectContent></Select></label><label>Agreement<Select value={entryAgreement} onValueChange={setEntryAgreement}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{store.agreements.map(a=><SelectItem key={a.id} value={a.id}>{a.id} · {a.vehicle}</SelectItem>)}</SelectContent></Select></label><label>Amount (BDT)<Input type="number" inputMode="numeric" min="1" step="1" value={entryAmount} onChange={e=>setEntryAmount(e.target.value)} placeholder="e.g. 8,000"/></label><label>Event date<Input type="date" value={entryDate} onChange={e=>setEntryDate(e.target.value)}/></label><label>Category<Select value={entryCategory} onValueChange={setEntryCategory}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{['Repair','Fuel','Toll / parking','Maintenance','Cleaning','Rent','Owner rent','Salary','Advance','Other'].map(x=><SelectItem value={x} key={x}>{x}</SelectItem>)}</SelectContent></Select></label><label>Reference<Input value={entryRef} onChange={e=>setEntryRef(e.target.value)} placeholder="Receipt / bank reference"/></label>{entryType==='Expense'&&<><label>Paid by<Select value={entryPayer} onValueChange={setEntryPayer}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{['Operator','Owner','Customer','Driver'].map(x=><SelectItem value={x} key={x}>{x}</SelectItem>)}</SelectContent></Select></label><label>Ultimately responsible<Select value={entryLiable} onValueChange={setEntryLiable}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{['Operator','Owner','Customer','Driver'].map(x=><SelectItem value={x} key={x}>{x}</SelectItem>)}</SelectContent></Select></label></>}</div><label>Description<Input value={entryDesc} onChange={e=>setEntryDesc(e.target.value)} placeholder="What happened?"/></label>{entryType==='Expense'&&<><label className="check-label"><input type="checkbox" checked={entryOffset} onChange={e=>setEntryOffset(e.target.checked)} disabled={entryLiable!=='Owner'||entryPayer!=='Operator'||!chosen?.rules.offset}/> Deduct an operator funded owner cost from owner rent (if authorized)</label><label>Receipt or proof <Input type="file" accept="image/*,.pdf" onChange={e=>setEntryReceipt(e.target.files?.[0]?.name||'')}/></label>{entryReceipt&&<button className="remove-receipt" onClick={()=>setEntryReceipt('')}>Remove {entryReceipt} ×</button>}</>}
 <div className="consequence"><strong><Eye size={16}/> Balance preview</strong><p>{!chosen||!amount?'Enter an amount to preview this entry.':entryType==='Expense'?`${entryPayer} pays ${money(amount)}; ${entryLiable} is responsible. ${entryLiable==='Owner'&&entryPayer==='Operator'&&entryOffset&&chosen.rules.offset?`Owner payable decreases by ${money(amount)} after approval.`:'No automatic owner offset.'}`:entryType==='Customer payment'?`Customer outstanding decreases by ${money(amount)} when posted.`:entryType==='Owner payout'?`Owner payable decreases by ${money(amount)} when posted.`:entryType==='Salary advance'?`Driver outstanding decreases by ${money(amount)} as an advance.`:`Driver outstanding decreases by ${money(amount)} when posted.`}{entryType==='Expense'&&amount>=5000?' Expense requires approval before balances change.':''}</p></div>{entryError&&<p role="alert" className="form-error">{entryError}</p>}</div><DialogFooter><Button variant="outline" onClick={()=>setEntryOpen(false)}>Cancel</Button><Button onClick={submitEntry} disabled={apiBusy}>{apiBusy?'Saving...':'Save entry'}</Button></DialogFooter></DialogContent></Dialog>
   <Dialog open={agreementOpen} onOpenChange={setAgreementOpen}><DialogContent className="agreement-dialog"><DialogHeader><DialogTitle>New rental agreement</DialogTitle><DialogDescription>Set the relationship and the monthly terms before activation.</DialogDescription></DialogHeader><div className="wizard-progress">{['Parties','Vehicle & driver','Monthly terms','Rules & review'].map((x,i)=><button key={x} className={wizardStep===i?'current':wizardStep>i?'done':''} onClick={()=>setWizardStep(i)}><span>{wizardStep>i?'✓':i+1}</span>{x}</button>)}</div><div className="wizard-body">{wizardStep===0&&<div className="form-grid"><label>Customer / billing party<Input value={newAgreement.customer} onChange={e=>setNewAgreement({...newAgreement,customer:e.target.value})} placeholder="Organization or person"/></label><label>Car owner<Input value={newAgreement.owner} onChange={e=>setNewAgreement({...newAgreement,owner:e.target.value})} placeholder="Owner's full name"/></label></div>}{wizardStep===1&&<div className="form-grid"><label>Vehicle name<Input value={newAgreement.vehicle} onChange={e=>setNewAgreement({...newAgreement,vehicle:e.target.value})} placeholder="e.g. Toyota Axio"/></label><label>Registration<Input value={newAgreement.registration} onChange={e=>setNewAgreement({...newAgreement,registration:e.target.value})} placeholder="DHA-METRO-..."/></label><label>Assigned driver<Input value={newAgreement.driver} onChange={e=>setNewAgreement({...newAgreement,driver:e.target.value})} placeholder="Driver name"/></label><label>Effective from<Input type="date" value={newAgreement.start} onChange={e=>setNewAgreement({...newAgreement,start:e.target.value})}/></label></div>}{wizardStep===2&&<div className="form-grid"><label>Customer rent / month (BDT)<Input type="number" min="1" value={newAgreement.rent} onChange={e=>setNewAgreement({...newAgreement,rent:e.target.value})}/></label><label>Owner rent / month (BDT)<Input type="number" min="1" value={newAgreement.ownerRent} onChange={e=>setNewAgreement({...newAgreement,ownerRent:e.target.value})}/></label><label>Driver salary / month (BDT)<Input type="number" min="1" value={newAgreement.salary} onChange={e=>setNewAgreement({...newAgreement,salary:e.target.value})}/></label></div>}{wizardStep===3&&<><div className="form-grid"><label>Fuel responsibility<Select value={newAgreement.fuel} onValueChange={v=>setNewAgreement({...newAgreement,fuel:v})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{['Owner','Operator','Customer'].map(x=><SelectItem value={x} key={x}>{x}</SelectItem>)}</SelectContent></Select></label><label>Repair responsibility<Select value={newAgreement.repair} onValueChange={v=>setNewAgreement({...newAgreement,repair:v})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{['Owner','Operator','Customer'].map(x=><SelectItem value={x} key={x}>{x}</SelectItem>)}</SelectContent></Select></label></div><label className="check-label"><input type="checkbox" checked={newAgreement.offset} onChange={e=>setNewAgreement({...newAgreement,offset:e.target.checked})}/> Permit owner cost offsets from owner rent</label><div className="consequence"><strong>Sample monthly statement</strong><p>Customer rent {money(Number(newAgreement.rent)||0)} · owner gross {money(Number(newAgreement.ownerRent)||0)} · driver salary {money(Number(newAgreement.salary)||0)}. Expenses and payments will be recorded separately.</p></div></>}{wizardError&&<p role="alert" className="form-error">{wizardError}</p>}</div><DialogFooter><Button variant="outline" onClick={()=>wizardStep?setWizardStep(wizardStep-1):setAgreementOpen(false)}>{wizardStep?'Back':'Cancel'}</Button><Button onClick={()=>wizardStep<3?setWizardStep(wizardStep+1):createAgreement()}>{apiBusy?'Saving...':wizardStep<3?'Continue':'Activate agreement'}</Button></DialogFooter></DialogContent></Dialog>
   <Dialog open={!!confirmClose} onOpenChange={o=>!o&&setConfirmClose(null)}><DialogContent><DialogHeader><DialogTitle>Close September settlement?</DialogTitle><DialogDescription>{confirmClose} · This marks the sample month as closed in your browser. Review all four statements and source entries first.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={()=>setConfirmClose(null)}>Keep open</Button><Button onClick={()=>confirmClose&&closeSettlement(confirmClose)}>Confirm close</Button></DialogFooter></DialogContent></Dialog>
   {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/>{toast}<button onClick={()=>setToast('')} aria-label="Dismiss"><X size={16}/></button></div>}
  </div>
}
function AccountTable({agreements,store,onSelect,sort,setSort}:{agreements:Agreement[];store:Store;onSelect:(x:string)=>void;sort:'customer'|'due';setSort:(x:'customer'|'due')=>void}){return <><Table><TableHeader><TableRow><TableHead><button onClick={()=>setSort('customer')}>Customer / vehicle {sort==='customer'?'↓':''}</button></TableHead><TableHead className="text-right">Billed</TableHead><TableHead className="text-right">Received</TableHead><TableHead className="text-right"><button onClick={()=>setSort('due')}>Customer due {sort==='due'?'↓':''}</button></TableHead><TableHead className="text-right">Owner due</TableHead><TableHead className="text-right">Driver due</TableHead><TableHead>Status</TableHead><TableHead/></TableRow></TableHeader><TableBody>{agreements.map(a=>{const s=statement(a,store.entries);return <TableRow className="click-row" key={a.id} onClick={()=>onSelect(a.id)}><TableCell><b>{a.customer}</b><small>{a.vehicle} · {a.id}</small></TableCell><TableCell className="text-right nums">{money(a.rent)}</TableCell><TableCell className="text-right nums">{money(s.received)}</TableCell><TableCell className="text-right nums due">{money(s.customerDue)}</TableCell><TableCell className="text-right nums">{money(s.ownerDue)}</TableCell><TableCell className="text-right nums">{money(s.driverDue)}</TableCell><TableCell><Badge tone={store.closed.includes(a.id)?'good':'blue'}>{store.closed.includes(a.id)?'Closed':'Open'}</Badge></TableCell><TableCell><button aria-label={'View '+a.id} className="row-link"><ChevronRight size={18}/></button></TableCell></TableRow>})}</TableBody></Table>{agreements.length===0&&<Empty text="No accounts match your search."/>}</>}
function EntryTable({entries,store,onSelect}:{entries:Entry[];store:Store;onSelect:(x:string)=>void}){return <><Table><TableHeader><TableRow><TableHead>Date / reference</TableHead><TableHead>Entry / vehicle</TableHead><TableHead>Paid by</TableHead><TableHead>Responsible</TableHead><TableHead className="text-right">Amount</TableHead><TableHead>Status</TableHead><TableHead/></TableRow></TableHeader><TableBody>{entries.map(e=><TableRow className="click-row" key={e.id} onClick={()=>onSelect(e.id)}><TableCell>{fmtDate(e.date)}<small>{e.reference}</small></TableCell><TableCell><b>{e.type}</b><small>{store.agreements.find(a=>a.id===e.agreementId)?.vehicle} · {e.id}</small></TableCell><TableCell>{e.paidBy}</TableCell><TableCell>{e.responsible}</TableCell><TableCell className="text-right nums">{money(e.amount)}</TableCell><TableCell><Badge tone={e.status==='Posted'?'good':e.status==='Reversed'?'bad':'warn'}>{e.status}</Badge></TableCell><TableCell><button aria-label={'View '+e.id} className="row-link"><ChevronRight size={18}/></button></TableCell></TableRow>)}</TableBody></Table>{entries.length===0&&<Empty text="No entries match these filters."/>}</>}
function reportConfig(type:string){switch(type){case 'Customer balances':return{party:'Customer',columns:['Billed','Received','Outstanding'],values:(a:Agreement,s:ReturnType<typeof statement>)=>[a.rent,s.received,s.customerDue]};case 'Owner liability':return{party:'Owner',columns:['Gross','Offsets','Paid','Due'],values:(a:Agreement,s:ReturnType<typeof statement>)=>[s.ownerGross,s.offsets,s.ownerPaid,s.ownerDue]};case 'Driver payroll':return{party:'Driver',columns:['Earned','Advance','Paid','Due'],values:(a:Agreement,s:ReturnType<typeof statement>)=>[s.driverEarned,s.advance,s.driverPaid,s.driverDue]};case 'Cash movement':return{party:'Customer',columns:['Receipts','Owner paid','Driver paid','Net cash'],values:(a:Agreement,s:ReturnType<typeof statement>)=>[s.received,s.ownerPaid,s.driverPaid,s.cash]};default:return{party:'Customer',columns:['Earned rent','Owner gross','Driver salary','Operator costs','Accrual margin'],values:(a:Agreement,s:ReturnType<typeof statement>)=>[a.rent,a.ownerRent,a.salary,s.operatorCosts,s.margin]}}}
function ReportTable({type,agreements,store,onSelect}:{type:string;agreements:Agreement[];store:Store;onSelect:(x:string)=>void}){const config=reportConfig(type);return <><Table><TableHeader><TableRow><TableHead>{config.party} / vehicle</TableHead>{config.columns.map(c=><TableHead className="text-right" key={c}>{c}</TableHead>)}<TableHead/></TableRow></TableHeader><TableBody>{agreements.map(a=>{const s=statement(a,store.entries);return <TableRow className="click-row" key={a.id} onClick={()=>onSelect(a.id)}><TableCell><b>{config.party==='Owner'?a.owner:config.party==='Driver'?a.driver:a.customer}</b><small>{a.vehicle} · {a.id}</small></TableCell>{config.values(a,s).map((n,i)=><TableCell className="text-right nums" key={i}>{n<0?'−':''}{money(n)}</TableCell>)}<TableCell><ChevronRight size={17}/></TableCell></TableRow>})}</TableBody></Table>{agreements.length===0&&<Empty text="No agreements match this report filter."/>}</>}
